shellCommands.command:
/bin/bash -lc "node --input-type=module <<'EOF'
import assert from 'node:assert/strict'

for (const [path, name, price, related] of [
  ['/products/lamp?currency=EUR', 'Brass lamp', 'EUR 110.40', 'Stone vase'],
  ['/products/lamp?currency=USD', 'Brass lamp', 'USD 120.00', 'Stone vase'],
  ['/products/vase?currency=EUR', 'Stone vase', 'EUR 73.60', 'Brass lamp'],
  ['/products/lamp?currency=EUR', 'Brass lamp', 'EUR 110.40', 'Stone vase'],
]) {
  const response = await fetch("'`http://127.0.0.1:3100${path}`)
  const reader = response.body.getReader()
  let html = '"''
  const chunks = []
  const start = Date.now()
  while (true) {
    const { value, done } = await reader.read()
    if (done) break
    const chunk = new TextDecoder().decode(value)
    html += chunk
    chunks.push({ ms: Date.now() - start, shell: chunk.includes('Signal Shop collection'), product: chunk.includes(price), related: chunk.includes(related) })
  }
  assert.equal(response.status, 200, path)
  assert.ok(html.includes(name), "'`${path}: missing product name`)
  assert.ok(html.includes(price), `${path}: missing price`)
  assert.ok(html.includes(related), `${path}: missing related product`)
  assert.ok(!html.includes(path.includes('"'EUR') ? 'USD 120.00' : 'EUR 110.40'), "'`${path}: wrong currency leaked`)
  console.log(path, JSON.stringify(chunks))
}
EOF'
